const przycisk2 = { id: "b" };
const klikniecia = new Map([[przycisk1, 0], [przycisk2, 0]]);

klikniecia.set(przycisk1, klikniecia.get(przycisk1) + 1);
klikniecia.set(przycisk1, klikniecia.get(przycisk1) + 1);

console.log(klikniecia.get(przycisk1)); // -> 2
console.log(klikniecia.get(przycisk2)); // -> 0
// W zwyklym obiekcie oba klucze staloby sie napisem "[object Object]".

const obiekt = { b: 1, 2: "x", a: 2, 1: "y" };
console.log(Object.keys(obiekt)); // -> ["1", "2", "b", "a"]

const mapa = new Map([["b", 1], [2, "x"], ["a", 2], [1, "y"]]);
console.log([...mapa.keys()]);    // -> ["b", 2, "a", 1]
// Map nie przestawia kluczy, obiekt stawia klucze calkowitoliczbowe na poczatku.

const konfiguracja = { motyw: "ciemny", jezyk: "pl" };
console.log(JSON.stringify(konfiguracja)); // -> {"motyw":"ciemny","jezyk":"pl"}

const mapa = new Map(Object.entries(konfiguracja));
console.log(JSON.stringify(mapa));         // -> {}
// Stale, znane pola serializuja sie do JSON bez dodatkowych krokow tylko w obiekcie.

function zliczSlowa(tekst) {
  const mapa = new Map();
  for (const slowo of tekst.split(" ")) {
    mapa.set(slowo, (mapa.get(slowo) ?? 0) + 1);
  }
  return mapa;
}

console.log(Object.fromEntries(zliczSlowa("a b a c b a"))); // -> { a: 3, b: 2, c: 1 }

const slowa = ["kot", "pies", "kot", "ryba", "pies", "kot"];
const licznik = new Map();
for (const s of slowa) licznik.set(s, (licznik.get(s) ?? 0) + 1);

let najlepsze = "";
let max = 0;
for (const [slowo, ile] of licznik) {
  if (ile > max) {
    max = ile;
    najlepsze = slowo;
  }
}

console.log(najlepsze, max); // -> kot 3

const odwiedziny = ["a", "b", "a", "c", "b"];
const odwiedzone = new Set();

for (const strona of odwiedziny) {
  console.log(strona, odwiedzone.has(strona) ? "juz byla" : "nowa");
  odwiedzone.add(strona);
}
// a nowa, b nowa, a juz byla, c nowa, b juz byla

const uzytkownicy = [{ id: 1, imie: "Ala" }, { id: 2, imie: "Jan" }];
const poId = new Map(uzytkownicy.map(u => [u.id, u]));

console.log(poId.get(2).imie);       // -> Jan
console.log(poId.get(9)?.imie ?? "brak"); // -> brak

const zadania = new Set();
const dodaj = zadanie => zadania.add(zadanie);

function przetwarzaj() {
  const pierwsze = zadania.values().next().value;
  zadania.delete(pierwsze);
  return pierwsze;
}

dodaj("a"); dodaj("b"); dodaj("a");
console.log(przetwarzaj()); // -> a
console.log(przetwarzaj()); // -> b
console.log(zadania.size);  // -> 0

const a = [1, 2, 3, 4];
const b = [3, 4, 5];
const zbiorB = new Set(b);

console.log(a.filter(x => zbiorB.has(x))); // -> [3, 4]
// has() dziala szybko niezaleznie od rozmiaru zbioru, includes() przeszukuje tablice za kazdym razem.

function pobierz(mapa, klucz, domyslna) {
  return mapa.has(klucz) ? mapa.get(klucz) : domyslna;
}

const mapa = new Map([["a", undefined]]);
console.log(pobierz(mapa, "a", 0)); // -> undefined (klucz istnieje)
console.log(pobierz(mapa, "b", 0)); // -> 0

const slownik = { jablko: 3, gruszka: 5 };
const mapa = new Map(Object.entries(slownik));

mapa.set("sliwka", 2);
mapa.delete("jablko");

console.log(Object.fromEntries(mapa)); // -> { gruszka: 5, sliwka: 2 }

const dozwolone = new Set([101, 102, 103]);

console.log(dozwolone.has(102)); // -> true
console.log(dozwolone.has(200)); // -> false
// Set jasno komunikuje "zbior wartosci", a has() jest szybkie i czytelne.

function pokazTyp(x) {
  if (x instanceof Map) return "Map";
  if (x instanceof Set) return "Set";
  if (Array.isArray(x)) return "tablica";
  return "obiekt";
}

console.log(pokazTyp(new Map()), pokazTyp(new Set()), pokazTyp([]), pokazTyp({}));
// -> Map Set tablica obiekt

